"""Public pages (home, privacy policy, terms) required by the OAuth branding."""

from starlette.requests import Request
from starlette.responses import HTMLResponse

from ads_mcp.coordinator import mcp

_PAGES = {
    '/': '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Turbo7 Agente Google Ads</title><style>:root{--bg:#fff;--fg:#1d1d1f;--mut:#555;--ac:#5b2bd6}@media (prefers-color-scheme:dark){:root{--bg:#121214;--fg:#eee;--mut:#aaa;--ac:#a98bff}}body{margin:0;background:var(--bg);color:var(--fg);font:16px/1.6 system-ui,sans-serif}main{max-width:760px;margin:0 auto;padding:40px 16px}a{color:var(--ac)}h1{font-size:28px}h2{font-size:20px;margin-top:28px}small,p.m{color:var(--mut)}nav a{margin-right:16px}</style></head><body><main><nav><a href="/">Início</a><a href="/privacidade">Política de Privacidade</a><a href="/termos">Termos de Serviço</a></nav><h1>Turbo7 Agente Google Ads</h1><p>Ferramenta interna da <strong>Turbo7 Marketing de Planejados</strong>, agência de tráfego pago para lojas de móveis planejados.</p><p>O Turbo7 Agente Google Ads conecta o assistente de IA Claude às contas de Google Ads gerenciadas pela agência, por meio do servidor MCP oficial do Google Ads. Ele é usado pela equipe da Turbo7 para consultar desempenho de campanhas, gerar relatórios e apoiar decisões de otimização.</p><p>O acesso é restrito à equipe da agência e às contas de clientes vinculadas à conta de administrador (MCC) da Turbo7.</p><p class="m"><small>Turbo7 Marketing de Planejados · Contato: pablo.sampaioturbo7@gmail.com · Atualizado em 31/10/2026</small></p></main></body></html>',
    '/privacidade': '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Política de Privacidade · Turbo7 Agente Google Ads</title><style>:root{--bg:#fff;--fg:#1d1d1f;--mut:#555;--ac:#5b2bd6}@media (prefers-color-scheme:dark){:root{--bg:#121214;--fg:#eee;--mut:#aaa;--ac:#a98bff}}body{margin:0;background:var(--bg);color:var(--fg);font:16px/1.6 system-ui,sans-serif}main{max-width:760px;margin:0 auto;padding:40px 16px}a{color:var(--ac)}h1{font-size:28px}h2{font-size:20px;margin-top:28px}small,p.m{color:var(--mut)}nav a{margin-right:16px}</style></head><body><main><nav><a href="/">Início</a><a href="/privacidade">Política de Privacidade</a><a href="/termos">Termos de Serviço</a></nav><h1>Política de Privacidade</h1><p>Esta política explica como o <strong>Turbo7 Agente Google Ads</strong>, ferramenta interna da Turbo7 Marketing de Planejados, trata os dados acessados por meio da Google Ads API, em conformidade com a Lei Geral de Proteção de Dados (LGPD, Lei 13.709/2018).</p>\n<h2>1. Dados acessados</h2><p>Com a autorização do usuário via login Google (escopo <code>https://www.googleapis.com/auth/adwords</code>), a ferramenta acessa dados das contas de Google Ads às quais esse usuário já tem permissão: estrutura de campanhas, métricas de desempenho (impressões, cliques, custo, conversões) e configurações de anúncios. Também é usado o endereço de e-mail da conta Google para identificar o usuário no login.</p>\n<h2>2. Finalidade</h2><p>Os dados são usados exclusivamente para gerar relatórios, análises e recomendações de otimização das campanhas dos clientes da Turbo7. Não são vendidos, cedidos ou usados para publicidade.</p>\n<h2>3. Armazenamento e segurança</h2><p>Os tokens de acesso OAuth ficam armazenados de forma criptografada no Google Cloud (Firestore) do projeto da Turbo7, apenas pelo tempo necessário para manter a sessão do usuário. Os dados de campanha são consultados sob demanda e não são guardados em banco próprio da ferramenta.</p>\n<h2>4. Compartilhamento</h2><p>Os resultados das consultas são processados pelo assistente de IA Claude, da Anthropic, utilizado pela equipe da Turbo7. Não há outro compartilhamento com terceiros.</p>\n<h2>5. Uso dos dados do Google</h2><p>O uso e a transferência de informações recebidas das APIs do Google seguem a <a href="https://developers.google.com/terms/api-services-user-data-policy">Política de Dados do Usuário dos Serviços de API do Google</a>, incluindo os requisitos de Uso Limitado.</p>\n<h2>6. Direitos do titular e revogação</h2><p>O usuário pode revogar o acesso a qualquer momento em <a href="https://myaccount.google.com/permissions">myaccount.google.com/permissions</a>. Pedidos de acesso, correção ou exclusão de dados podem ser feitos pelo e-mail abaixo.</p>\n<h2>7. Contato</h2><p>Turbo7 Marketing de Planejados · pablo.sampaioturbo7@gmail.com</p><p class="m"><small>Turbo7 Marketing de Planejados · Contato: pablo.sampaioturbo7@gmail.com · Atualizado em 31/10/2026</small></p></main></body></html>',
    '/termos': '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Termos de Serviço · Turbo7 Agente Google Ads</title><style>:root{--bg:#fff;--fg:#1d1d1f;--mut:#555;--ac:#5b2bd6}@media (prefers-color-scheme:dark){:root{--bg:#121214;--fg:#eee;--mut:#aaa;--ac:#a98bff}}body{margin:0;background:var(--bg);color:var(--fg);font:16px/1.6 system-ui,sans-serif}main{max-width:760px;margin:0 auto;padding:40px 16px}a{color:var(--ac)}h1{font-size:28px}h2{font-size:20px;margin-top:28px}small,p.m{color:var(--mut)}nav a{margin-right:16px}</style></head><body><main><nav><a href="/">Início</a><a href="/privacidade">Política de Privacidade</a><a href="/termos">Termos de Serviço</a></nav><h1>Termos de Serviço</h1><p>O <strong>Turbo7 Agente Google Ads</strong> é uma ferramenta interna da Turbo7 Marketing de Planejados, de uso restrito à equipe da agência.</p>\n<h2>1. Uso permitido</h2><p>A ferramenta só pode ser usada para consultar e gerenciar contas de Google Ads às quais o usuário tenha permissão legítima, em nome dos clientes da Turbo7.</p>\n<h2>2. Responsabilidades</h2><p>O usuário é responsável pelas ações realizadas com sua conta Google. Alterações em campanhas exigem confirmação explícita da equipe antes de serem executadas.</p>\n<h2>3. Disponibilidade</h2><p>A ferramenta é fornecida no estado em que se encontra, sem garantia de disponibilidade contínua, e pode ser alterada ou descontinuada a qualquer momento.</p>\n<h2>4. Políticas do Google</h2><p>O uso está sujeito aos <a href="https://developers.google.com/google-ads/api/docs/api-policy/terms">Termos e Condições da Google Ads API</a> e às políticas de publicidade do Google.</p>\n<h2>5. Contato</h2><p>pablo.sampaioturbo7@gmail.com</p><p class="m"><small>Turbo7 Marketing de Planejados · Contato: pablo.sampaioturbo7@gmail.com · Atualizado em 31/10/2026</small></p></main></body></html>',
}


def _make_handler(path: str):
    async def handler(request: Request) -> HTMLResponse:
        return HTMLResponse(_PAGES[path])

    return handler


for _path in _PAGES:
    mcp.custom_route(_path, methods=["GET"], include_in_schema=False)(
        _make_handler(_path)
    )
